// 参考解：双指针归并
#include <iostream>
using namespace std;

struct LNode {
    int data;
    LNode *next;
};

typedef LNode *LinkList;

LinkList build(int n) {
    LinkList L = new LNode;
    L->next = nullptr;
    LNode *r = L;
    for (int i = 0; i < n; i++) {
        int v; cin >> v;
        LNode *s = new LNode;
        s->data = v; s->next = nullptr;
        r->next = s; r = s;
    }
    return L;
}

int main() {
    int n, m;
    if (!(cin >> n)) return 0;
    LinkList A = build(n);
    cin >> m;
    LinkList B = build(m);

    LNode *p = A->next, *q = B->next, *r = A;
    while (p != nullptr && q != nullptr) {
        if (p->data <= q->data) { r->next = p; r = p; p = p->next; }
        else                    { r->next = q; r = q; q = q->next; }
    }
    r->next = (p != nullptr) ? p : q;
    delete B;

    if (A->next == nullptr) {
        cout << "empty\n";
    } else {
        for (LNode *t = A->next; t != nullptr; t = t->next) {
            cout << t->data << (t->next == nullptr ? '\n' : ' ');
        }
    }
    return 0;
}
